package chat.oldy;
import android.graphics.*;import android.view.*;import android.widget.*;import org.json.JSONObject;

final class YouTubeCards {
 static void add(MainActivity a,LinearLayout bubble,YouTubeLinkDetector.Target t,JSONObject link,boolean wide){a.space(bubble,8);LinearLayout card=a.col();a.pad(card,11);card.setBackground(a.glass(17));TextView provider=a.label("▶ YouTube",12,a.light?0xffaa293b:0xffff8c99);provider.setTypeface(null,1);card.addView(provider);TextView title=a.label(link.optString("title",I18n.t("Видео на YouTube")),15,a.TEXT);title.setMaxLines(3);title.setTypeface(null,1);title.setPadding(0,a.dp(5),0,a.dp(8));card.addView(title);if(!t.videoId.isEmpty()){FrameLayout preview=new FrameLayout(a);ImageView image=new ImageView(a);image.setScaleType(ImageView.ScaleType.CENTER_CROP);preview.setBackground(a.shape(a.light?0xffccd9e5:0xff20334a,13));preview.setClipToOutline(true);preview.addView(image,new FrameLayout.LayoutParams(-1,-1));NeonPlay play=new NeonPlay(a);preview.addView(play,new FrameLayout.LayoutParams(a.dp(54),a.dp(54),Gravity.CENTER));preview.setOnClickListener(v->OldiYouTubePlayer.open(a,t,title.getText().toString()));card.addView(preview,new LinearLayout.LayoutParams(wide?-1:a.dp(224),a.dp(150)));Bitmap cached=a.mediaCache.get("yt:"+t.videoId);if(cached!=null)image.setImageBitmap(cached);else Art.fetch.execute(()->{try{Bitmap bitmap=YouTubePreviewProvider.thumbnail(t.videoId);if(bitmap!=null){a.mediaCache.put("yt:"+t.videoId,bitmap);a.runOnUiThread(()->image.setImageBitmap(bitmap));}}catch(Exception ignored){}});
   Art.fetch.execute(()->{try{JSONObject info=YouTubePreviewProvider.metadata(t.videoId);String name=info.optString("title");if(!name.isEmpty()&&name.length()<=300)a.runOnUiThread(()->title.setText(name));}catch(Exception ignored){}});
  }a.space(card,8);card.addView(a.button(I18n.t("▶ Смотреть в Oldi"),true,()->OldiYouTubePlayer.open(a,t,title.getText().toString())));a.space(card,5);TextView external=a.button(I18n.t("Открыть в YouTube"),false,()->OldiYouTubePlayer.external(a,t));external.setTextSize(12);card.addView(external);bubble.addView(card,new LinearLayout.LayoutParams(wide?-1:-2,-2));}
}
